mermaid:
erDiagram
  customers {
    customer_id int PK
    name string
    country string
  }
  categories {
    id int PK
    name string
  }
  products {
    product_id int PK
    name string
    category_id int
  }
  addresses {
    address_id int PK
    customer_id int
    city string
  }
  orders {
    order_id int PK
    customer_id int
    order_date date
    ship_to_id int
  }
  order_items {
    order_id int PK
    line_no int PK
    product_id int
    quantity double
  }
  audit_log {
    event string
    customer_id int
    happened_at timestamp
  }
  addresses ||--o{ orders : "ship_to_id confirmed"
  categories ||--o{ products : "category_id R1"
  customers ||--o{ addresses : "customer_id R1"
  customers ||--o{ orders : "customer_id R1"
  orders ||--o{ order_items : "order_id R1"
  products ||--o{ order_items : "product_id R1"
  customers ||--o{ audit_log : "customer_id R1"
